class CSVParser:
    def __init__(self, csv: str):
        self.csv = csv

    def contents(self) -> list[list[str]]:
        lines = self.csv.split("\n")
        output = []
        for line in lines:
            output.append(line.split(","))
        return output

    def header(self) -> list[str]:
        lines = self.csv.split("\n")
        if not lines:
            return []
        return lines[0].split(",")

from typing import List, Literal, Tuple
from queue import PriorityQueue
import math

Move = Literal["up", "down", "left", "right"]
# 0 = up, 1 = down, 2 = left, 3 = right
MoveIndex = Literal[0, 1, 2, 3]
# 0 = empty, 1 = wall, 2 = start, 3 = end
Cell = Literal[0, 1, 2, 3]


class Maze:
    def __init__(self, maze: List[List[Cell]]):
        self.maze = maze
        self.rows = len(maze)
        self.cols = len(maze[0])
        self.start = self.find_start()
        self.end = self.find_end()

    def find_start(self) -> Tuple[int, int]:
        for row in range(self.rows):
            for col in range(self.cols):
                if self.maze[row][col] == 2:
                    return row, col
        raise ValueError("No start found")

    def find_end(self) -> Tuple[int, int]:
        for row in range(self.rows):
            for col in range(self.cols):
                if self.maze[row][col] == 3:
                    return row, col
        raise ValueError("No end found")

    def get_neighbors(self, row: int, col: int) -> List[Tuple[int, int]]:
        neighbors = []
        if row > 0 and self.maze[row - 1][col] != 1:
            neighbors.append((row - 1, col))
        if row < self.rows - 1 and self.maze[row + 1][col] != 1:
            neighbors.append((row + 1, col))
        if col > 0 and self.maze[row][col - 1] != 1:
            neighbors.append((row, col - 1))
        if col < self.cols - 1 and self.maze[row][col + 1] != 1:
            neighbors.append((row, col + 1))
        return neighbors

    def solve(self) -> Tuple[int, List[Tuple[int, int]]]:
        """
        Uses A* with Manhattan distance as the heuristic to find a path from start to end,
        returning the number of nodes expanded and the path if one exists.
        """
        visited = set()
        frontier = PriorityQueue()
        # Priority queue stores (priority, current position, path)
        # Priority is cost + heuristic (Manhattan distance)
        frontier.put((0, self.start, []))
        expanded = 0

        while not frontier.empty():
            priority, current, path = frontier.get()

            if current in visited:
                continue

            visited.add(current)
            new_path = path + [current]

            if current == self.end:
                return expanded, new_path

            for neighbor in self.get_neighbors(*current):
                if neighbor not in visited:
                    # Calculate cost (actual cost from start to neighbor)
                    cost = len(new_path) + 1
                    # Calculate heuristic (Manhattan distance to goal)
                    heuristic = abs(neighbor[0] - self.end[0]) + abs(neighbor[1] - self.end[1])
                    # Total priority = cost + heuristic
                    frontier.put((cost + heuristic, neighbor, new_path))

            expanded += 1

        return expanded, []

class Matrix:

    def __init__(self, matrix: list[list[int]]):
        self.matrix = matrix

    def same_size(self, other):
        return len(self.matrix) == len(other.matrix) and len(self.matrix[0]) == len(other.matrix[0])

    def add(self, other):
        if not self.same_size(other):
            raise ValueError("Matrices must be of the same size for addition.")
        result = []
        for i in range(len(self.matrix)):
            row = []
            for j in range(len(self.matrix[0])):
                row.append(self.matrix[i][j] + other.matrix[i][j])
            result.append(row)
        return Matrix(result)

    def subtract(self, other):
        if not self.same_size(other):
            raise ValueError("Matrices must be of the same size for subtraction.")
        result = []
        for i in range(len(self.matrix)):
            row = []
            for j in range(len(self.matrix[0])):
                row.append(self.matrix[i][j] - other.matrix[i][j])
            result.append(row)
        return Matrix(result)

    def transpose(self):
        result = []
        for i in range(len(self.matrix[0])):
            row = []
            for j in range(len(self.matrix)):
                row.append(self.matrix[j][i])
            result.append(row)
        return Matrix(result)

import pandas as pd
import random
import string


class GradeManipulator:

    def __init__(self):
        self.data = self._generate_random_data()

    def _generate_random_data(self):
        names = [''.join(random.choices(string.ascii_uppercase, k=5))
                 for _ in range(100)]
        ages = [random.randint(15, 25) for _ in range(100)]
        grades = random.choices(['A', 'B', 'C', 'D', 'F'], k=100)
        scores = [random.randint(0, 100) for _ in range(100)]

        return pd.DataFrame({
            'Name': names,
            'Age': ages,
            'Grade': grades,
            'Score': scores
        })

    def average_score_by_grade(self):
        return self.data.groupby('Grade')['Score'].mean()

    def top_scorers(self, n):
        return self.data.sort_values('Score', ascending=False).head(n)

"""
A programming language interpreter for the following language:
expr ::= expr <binop> expr | <number> | <name> | var <name> = <expr> in <expr>
binop ::= + | - | * | /
"""
from abc import ABC, abstractmethod


class AST(ABC):
    @abstractmethod
    def eval(self, env) -> int:
        pass


class BinOp(AST):
    def __init__(self, left: AST, op: str, right: AST):
        self.left = left
        self.op = op
        self.right = right

    def eval(self, env) -> int:
        left = self.left.eval(env)
        right = self.right.eval(env)
        if self.op == "+":
            return left + right
        elif self.op == "-":
            return left - right
        elif self.op == "*":
            return left * right
        elif self.op == "/":
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            return left // right
        else:
            raise ValueError(f"Unknown operator: {self.op}")


class Var(AST):
    def __init__(self, name: str, bound: AST, body: AST):
        self.name = name
        self.bound = bound
        self.body = body

    def eval(self, env) -> int:
        new_env = env.copy()
        new_env[self.name] = self.bound.eval(env)
        return self.body.eval(new_env)


class Number(AST):
    def __init__(self, value: int):
        self.value = value

    def eval(self, _) -> int:
        return self.value


class Name(AST):
    def __init__(self, name: str):
        self.name = name

    def eval(self, env) -> int:
        if self.name not in env:
            raise ValueError(f"Unknown variable: {self.name}")
        return env[self.name]

class Quiz:

    def __init__(self, questions, answers):
        self.questions = questions
        self.answers = answers
        self.total_questions = len(questions)
        self.score = 0
        self.current_question = 0
        self.skipped = 0

    def check_answer(self, question_index, answer) -> bool:
        if self.answers[question_index] == answer:
            self.score += 1
            return True
        return False

    def next_question(self):
        if self.current_question == self.total_questions:
            raise IndexError("No more questions!")
        else:
            q = self.questions[self.current_question]
            self.current_question += 1
            return q

    def add_question(self, question, answer):
        self.questions.append(question)
        self.answers.append(answer)
        self.total_questions += 1

    def skip_question(self):
        self.skipped += 1
        self.current_question += 1

    def display_results(self):
        return f"Total Questions: {self.total_questions}\nTotal Points Obtained: {self.score}\nQuestions Skipped: {self.skipped}"

import random


class Card:
    def __init__(self, suit, value):
        self.suit = suit
        self.value = value

    def __str__(self):
        return f"{self.value} of {self.suit}"


class Deck:
    def __init__(self):
        self.cards = []
        self.build()

    def build(self):
        for suit in ["Spades", "Clubs", "Diamonds", "Hearts"]:
            for value in ["2", "3", "4", "5", "6", "7", "8", "9", "10", "Jack", "Queen", "King", "Ace"]:
                self.cards.append(Card(suit, value))

    def shuffle(self):
        random.shuffle(self.cards)

    def draw(self):
        if not self.cards:
            return None
        return self.cards.pop(0)


class Player:
    def __init__(self, name):
        self.name = name
        self.hand = []

    def show_hand(self):
        return [str(card) for card in self.hand]

    def receive_card(self, card):
        self.hand.append(card)


class Game:
    def __init__(self, players):
        self.players = [Player(name) for name in players]
        self.deck = Deck()
        self.deck.shuffle()

    def distribute_cards(self):
        while self.deck.cards:
            for player in self.players:
                card = self.deck.draw()
                if card is not None:
                    player.receive_card(card)

    def show_all_hands(self):
        hands = []
        for player in self.players:
            hands.append(player.show_hand())
        return hands

from typing import List, Union
import re


class HTMLElement:
    def __init__(self, name, content: List[Union[str, 'HTMLElement']], attributes: dict = None):
        self.name = name
        self.content = content
        self.attributes = attributes or {}

    def __str__(self):
        attrs = ' '.join(f'{k}="{v}"' for k, v in self.attributes.items())
        return f"<{self.name}{f' {attrs}' if attrs else ''}>{''.join(str(c) for c in self.content)}</{self.name}>"

    def __repr__(self):
        return f"HTMLElement(name={self.name}, content={repr(self.content)}, attributes={repr(self.attributes)})"


def parse(content: str) -> List[HTMLElement]:
    """
    Parses the given HTML content and returns a list of HTMLElements.
    """
    tokens = tokenize(content)
    stack = []
    result = []

    for token in tokens:
        if is_start_tag(token):
            tag_info = get_tag_info(token)
            stack.append(HTMLElement(tag_info['name'], [], tag_info['attributes']))
        elif is_end_tag(token):
            element = stack.pop()
            if stack:
                stack[-1].content.append(element)
            else:
                result.append(element)
        else:
            if stack:
                stack[-1].content.append(token)

    return result


def tokenize(content: str) -> List[str]:
    # This regex splits the content into tags and text.
    # It looks for anything that starts with '<' and ends with '>', and treats it as a tag.
    # Everything else is treated as text.
    return re.findall(r'<[^>]+>|[^<]+', content)


def is_start_tag(token: str) -> bool:
    # A start tag starts with '<' but does not start with '</'.
    return token.startswith('<') and not token.startswith('</')


def is_end_tag(token: str) -> bool:
    # An end tag starts with '</'.
    return token.startswith('</')


def get_tag_info(token: str) -> dict:
    # Extracts the tag name and attributes from a token.
    # Returns a dictionary with 'name' and 'attributes' keys.
    tag_name = get_tag_name(token)
    attributes = get_attributes(token)
    return {'name': tag_name, 'attributes': attributes}


def get_tag_name(token: str) -> str:
    # Extracts the tag name from a token.
    # It removes '<', '>', and '/' from the token to get the tag name.
    return token.strip('</>').split()[0]


def get_attributes(token: str) -> dict:
    # Extracts the attributes from a token.
    # Returns a dictionary of attributes.
    if not is_start_tag(token):
        return {}

    # Extract the part of the token after the tag name
    tag_part = token.split('>', 1)[0]
    tag_name, rest = tag_part.split(' ', 1) if ' ' in tag_part else (tag_part, '')

    # Parse attributes
    attributes = {}
    if rest:
        pairs = rest.split()
        for pair in pairs:
            if '=' in pair:
                key, value = pair.split('=', 1)
                # Handle cases where value is enclosed in quotes
                if value.startswith('"') and value.endswith('"'):
                    value = value[1:-1]
                elif value.startswith("'") and value.endswith("'"):
                    value = value[1:-1]
                attributes[key.strip()] = value.strip()
    return attributes

