    vowel_count = 0
    vowels = set("aeiouy")
    diphthongs = {"ae", "oe", "ei", "ea", "ia", "io", "aea"}
    line = prepare_line(line)
    i = 0
    while i < len(line):
        if i + 1 < len(line) and line[i:i+2] in diphthongs:
            i += 2
        else:
            if line[i] in vowels:
                vowel_count += 1
            i += 1
    return vowel_count

