    curr_max = lst[0]
    start_idx = 0
    end_idx = 0

    for i in range(1, len(lst)):
        if curr_max + lst[i] > lst[i]:
            curr_max += lst[i]
        else:
            curr_max = lst[i]
            start_idx = i

