class Sorter:
    def __init__(self):
        pass

    def sort(self, nums: list[int]) -> None:
        if len(nums) <= 1:
            return
        pivot = nums[0]
        left = [x for x in nums[1:] if x <= pivot]
        right = [x for x in nums[1:] if x > pivot]
        self.sort(left)
        self.sort(right)
        nums.clear()
        nums.extend(left)
        nums.append(pivot)
        nums.extend(right)

    def insert(self, nums: list[int], num: int) -> list[int]:
        output = []
        for n in nums:
            if num < n:
                output.append(num)
                return output + nums
            else:
                output.append(n)
        return output + [num]

