def cycle_equality(c1, c2):
    """
    Takes two lists, c1 and c2, and returns True if the two lists represent the same cycle within a permutation group. 
    """
    if len(c1) != len(c2):
        return False
    start_index_b = c2.index(c1[0]) if c1[0] in c2 else -1

    if start_index_b == -1:
        return False
    return c1 == c2[start_index_b:] + c2[:start_index_b]

def permutation_equality(p1, p2):
    """Takes two lists of disjoint cycles that represent two permutation groups, and returns True if they are the same permutation group."""
    if len(p1) != len(p2):
        return False
    hit_count = 0
    for c1 in p1:
        for c2 in p2:
            if cycle_equality(c1, c2):
                hit_count += 1
                break  # Once a match is found, move to the next cycle in p1
    return hit_count == len(p1)

def permutation_equality(p1, p2):
    """Takes two disjoint cycles that represent two permutation groups, and returns True if they are the same permutation group."""
    if len(p1) != len(p2):
        return False
    used = [False] * len(p2)
    hits = 0
    for c1 in p1:
        found = False
        for i, c2 in enumerate(p2):
            if not used[i] and cycle_equality(c1, c2):
                used[i] = True
                hits += 1
                found = True
                break
        if not found:
            return False
    return hits == len(p1)

from typing import Any, List


class Free:
    def __repr__(self):
        return "Free"


# singleton
FREE = Free()


class MemoryAllocation:
    def __init__(self, size, address, buf):
        self.size = size
        self.address = address
        self.buffer = buf

    def __repr__(self):
        return f"MemoryAllocation(size={self.size}, address={self.address})"

    def write(self, data: List[Any]):
        # Calculate how much can be written without exceeding the buffer
        max_write = min(len(data), self.size - (self.address - self.buffer))
        for i in range(max_write):
            self.buffer[self.address + i] = data[i]
        # Update the address to reflect how much was written
        self.address += max_write


class MemoryAllocator:
    def __init__(self, max_size):
        self.max_size = max_size
        self.buffer: List[Any] = [FREE] * max_size
        self.current = 0

    def allocate(self, size):
        if self.current + size > self.max_size:
            return None
        else:
            self.current += size
            return MemoryAllocation(size, self.current - size, self.buffer)

def write(self, data: List[Any]):
    for ex in data:
        if self.address < len(self.buffer):
            self.buffer[self.address] = ex
            self.address += 1

