            args.append(f"{arg.arg}: {annotation}")
        else:
            args.append(arg.arg)
    function_signature = f"{name}({', '.join(args)}): {return_annotation}"
    docstring = ast.get_docstring(node)
    if docstring is None:
        docstring = ""
    results.append((function_signature, docstring))

