                        if scaled > max_a_val:
                            max_a_val = scaled
                            best_actions = [a]
                        elif scaled == max_a_val:
                            best_actions.append(a)

                    v[i][j] = max_a_val
                    delta = max(delta, abs(v[i][j] - v[i][j]))  # This line is redundant, but kept for structure

        if delta < theta:
            break

    for i in range(len(p)):
        for j in range(len(p[i])):
            s = (i, j)
            if p[i][j] != "TERM":
                max_a_val = float('-inf')
                best_actions = []

                for a in actions:
                    s_next = next_state(s, a)
                    i_next, j_next = s_next
                    r = -1
                    scaled = r + v[i_next][j_next]
                    if scaled > max_a_val:
                        max_a_val = scaled
                        best_actions = [a]
                    elif scaled == max_a_val:
                        best_actions.append(a)

                p[i][j] = best_actions

import math

def permutation(n, r):
    return int(math.factorial(n) / math.factorial(n - r))

def combination(n, r):
    return int(math.factorial(n) / (math.factorial(r) * math.factorial(n - r)))

def arrangement_unlimited_rep(n, r):
    return int(n ** r)


def combination_unlimited_rep(n, r):
    return int(combination(n + r - 1, n))


def arrangement_restricted_rep(n, rList):
    product = 1

    for r in rList:
        product *= math.factorial(r)

    return int(math.factorial(n) / product)

from typing import Literal, List

Token = Literal["expr", ";", "if", "(", ")", "for", ",", "other"]
NonTerminal = Literal["stmt", "optexpr"]


class ParseTree:
    def __init__(self, children, nonterminal: NonTerminal):
        self.children = children
        self.nonterminal = nonterminal

    def __eq__(self, obj) -> bool:
        if not isinstance(obj, ParseTree):
            return False
        if isinstance(obj, ParseTree) and obj.nonterminal != self.nonterminal:
            return False
        else:
            if len(self.children) != len(obj.children):
                return False
            else:
                for i, child in enumerate(obj.children):
                    if child != self.children[i]:
                        return False
            return True


class Parser:
    Malformed = ValueError("input is not in the language accepted by this grammar")

    def __init__(self):
        self.inputs = []
        self.lookahead = 0

    def parse(self, inputs: List[Token]) -> ParseTree:
        self.inputs = inputs
        self.lookahead = 0
        temp = self.stmt()
        if self.lookahead != len(self.inputs):
            raise Parser.Malformed
        else:
            return temp

    def match(self, terminal: Token):
        if terminal == self.inputs[self.lookahead]:
            self.lookahead += 1
        else:
            raise Parser.Malformed

    def stmt(self) -> ParseTree:
        if self.lookahead >= len(self.inputs):
            raise Parser.Malformed
        match self.inputs[self.lookahead]:
            case "expr":
                self.match("expr")
                self.match(";")
                return ParseTree(["expr", ";"], "stmt")
            case "if":
                self.match("if")
                self.match("(")
                self.match("expr")
                self.match(")")
                return ParseTree(["if", "(", "expr", ")", self.stmt()], "stmt")
            case "for":
                self.match("for")
                self.match("(")
                optexpr1 = self.optexpr()
                self.match(";")
                optexpr2 = self.optexpr()
                self.match(";")
                optexpr3 = self.optexpr()
                self.match(")")
                return ParseTree(["for", "(", optexpr1, ";", optexpr2, ";", optexpr3, ")", self.stmt()], "stmt")
            case "other":
                self.match("other")
                return ParseTree(["other"], "stmt")
            case _:
                raise Parser.Malformed

    def optexpr(self) -> ParseTree:
        if self.lookahead >= len(self.inputs):
            raise Parser.Malformed
        if self.inputs[self.lookahead] == ";":
            self.match(";")
            return ParseTree([";"], "optexpr")
        else:
            self.match("expr")
            return ParseTree(["expr"], "optexpr")

from typing import List


class Matrix:
    def __init__(self, content: List[List[int]]) -> None:
        num_cols = None
        for row in content:
            if num_cols is None:
                num_cols = len(row)
            else:
                if len(row) != num_cols:
                    raise ValueError
        self.content = content

    def transpose(self) -> None:
        new_content = [
            [0 for i in range(len(self.content))] for i in range(len(self.content[0]))
        ]
        for row in range(len(self.content)):
            for col in range(len(self.content[row])):
                new_content[col][row] = self.content[row][col]
        self.content = new_content

    def determinant(self) -> int:
        assert len(self.content) == len(self.content[0]), "Matrix must be square"

        if len(self.content) == 2:
            return (
                self.content[0][0] * self.content[1][1]
                - self.content[0][1] * self.content[1][0]
            )
        elif len(self.content) == 3:
            t = self.content
            return (
                t[0][0] * (t[1][1] * t[2][2] - t[1][2] * t[2][1])
                - t[1][0] * (t[0][1] * t[2][2] - t[0][2] * t[2][1])
                + t[2][0] * (t[0][1] * t[1][2] - t[0][2] * t[1][1])
            )
        else:
            raise NotImplementedError("Determinant is not supported for matrices larger than 3x3")

