def has_permission(self, request, view):
    if request.method != 'POST':
        raise exceptions.MethodNotAllowed(method=request.method)
    data = request.data
    if not data:
        raise exceptions.ParseError('Request body is empty')
    if not settings.MAILGUN_API_KEY:
        return False
    signature = hmac.new(
        key=settings.MAILGUN_API_KEY,
        msg='{}{}'.format(
            data['timestamp'],
            data['token'],
        ),
        digestmod=hashlib.sha256,
    ).hexdigest()
    if 'signature' not in data:
        error_message = 'Signature required in request body'
        sentry.log_message(error_message)
        raise exceptions.ParseError(error_message)
    if not hmac.compare_digest(unicode(signature), unicode(data['signature'])):
        raise exceptions.ParseError('Invalid signature')
    return True

def get_default_time_display(dt, show_timezone=True):
    """
    Converts a datetime to a string representation. This is the default
    representation used in Studio and LMS.
    It is of the form "Apr 09, 2013 at 16:00" or "Apr 09, 2013 at 16:00 UTC",
    depending on the value of show_timezone.

    If None is passed in for dt, an empty string will be returned.
    The default value of show_timezone is True.
    """
    if dt is None:
        return ""
    timezone = ""
    if show_timezone:
        if dt.tzinfo is not None:
            try:
                timezone = " " + dt.tzinfo.tzname(dt)
            except NotImplementedError:
                timezone = dt.strftime('%z')
        else:
            timezone = " UTC"
    return dt.strftime("%b %d, %Y at %H:%M") + timezone

