def pad_list_sequences(sequence_list, length=None):
    """Pad Python List of unpadded tensors. If length is 
       not specified padding till sentence of max length."""
    if length is None:
        length = max(s.size(0) for s in sequence_list)
    padded_list = [pad_single_sequence(s, length) for s in sequence_list]
    return torch.cat(padded_list, dim=1)

def _init_sublayouts(self):
    ratio = self.ratio
    expand = self.expand
    master_windows = self.master_windows
    arrangement = self.arrangement

    class MasterWindows(HorizontalStack):
        def filter(self, client):
            return self.index_of(client) < master_windows
        def request_rectangle(self, r, windows):
            return (r, Rect())

    class SlaveWindows(HorizontalStack):
        def filter(self, client):
            return self.index_of(client) >= master_windows
        def request_rectangle(self, r, windows):
            if self.autohide and not windows:
                return (Rect(), r)
            else:
                if arrangement == "top":
                    rmaster, rslave = r.split_horizontal(ratio=ratio)
                else:
                    rslave, rmaster = r.split_horizontal(ratio=(1 - ratio))
                return (rslave, rmaster)

    self.sublayouts.append(SlaveWindows(self.clientStack,
                                        self.theme,
                                        parent=self,
                                        autohide=expand
                                        )
                           )
    self.sublayouts.append(MasterWindows(self.clientStack,
                                         self.theme,
                                         parent=self,
                                         autohide=expand
                                         )
                           )

def split_word(word):
    if len(word) < 1:
        raise Exception("You obviously need at least one letter to split a word")
    split_indexes = list(range(1, len(word)))
    for i in split_indexes:
        first_part = word[:i]
        second_part = word[i:]
        yield (first_part, second_part)

def _init_legends(self, legends, default_legend, layer_type):
    if isinstance(legends, list):
        legend_list = []
        for legend in legends:
            if isinstance(legend, Legend):
                if legend._type == 'default' or legend._type == 'basic':
                    legend._type = _get_simple_legend_geometry_type(layer_type)
                if legend._type == 'default' and default_legend:
                    legend._prop = default_legend._prop
                legend_list.append(legend)
            else:
                raise ValueError('Legends list contains invalid elements')
        return legend_list
    else:
        return []

