def resolve_duplicates(model, attr):
    v0, v1 = aliased(model, name="v0"), aliased(model, name="v1")
    query = db.session.query(v0).join(v1, and_(
        getattr(v0, attr) == getattr(v1, attr),
        v0.id > v1.id
    ))
    for v in query:
        if not hasattr(v, attr):
            setattr(v, attr, getattr(v, attr, model.type) + u"-" + unicode(v.id))
        else:
            setattr(v, attr, getattr(v, attr) + u"-" + unicode(v.id))
        db.session.add(v)
    db.session.commit()

def raise_on_error(r):
    if r.status_code >= 400:
        error = ''
        if 'errors' in r.json():
            error = r.json()['errors'][0]['message']
        elif r.text:
            try:
                response = json.loads(r.text)
                if 'message' in response:
                    # JIRA 5.1 errors
                    error = response['message']
                elif 'errorMessages' in response:
                    # JIRA 5.0.x error messages sometimes come wrapped in this array
                    errorMessages = response['errorMessages']
                    if isinstance(errorMessages, (list, tuple)) and len(errorMessages) > 0:
                        error = errorMessages[0]
                    else:
                        error = errorMessages
                else:
                    error = r.text
            except ValueError:
                error = r.text
        raise JIRAError(r.status_code, error, r.url)

def to_python(self, value):
    if value is None:
        return None

    repeats = value['repeats']

    if repeats == 'monthly':
        return ScheduleSet(include=[
            Schedule(days=[int(value['repeatOn'])])
        ])
    elif repeats == 'weekly':
        schedules = []
        for repeat_on in value['repeatOn']:
            if Decimal(repeat_on['from']) >= Decimal(repeat_on['to']):
                raise ValidationError(_('"From" is greater than or equal to "to".'),
                                      code='invalid')

            schedule = Schedule(
                weekdays=[int(repeat_on['weekday'])],
                days=[],
                seconds_of_the_day=list(range(
                    int(Decimal(repeat_on['from']) * 60 * 60),
                    int(Decimal(repeat_on['to']) * 60 * 60)
                )),
                seconds=[], minutes=[], hours=[]
            )
            schedules.append(schedule)

        return ScheduleSet(include=schedules)
    else:
        raise ValueError

